#!/usr/bin/env bash
# PreToolUse hook (matcher: Bash) — block a short list of destructive commands.
#
# Exit codes for this event:
#   0  continue. The normal permission flow decides.
#   2  block the tool call. Claude receives stderr as the reason and can adapt.
# Any other exit code is a non-blocking error, so a policy hook must use 2.
#
# If the input cannot be parsed, the hook exits 0 (fails open) so a broken hook
# never stops all work. Tighten that if your policy needs it.
#
# Generated by tq-forge. Add your own rules to RULES below.

set -uo pipefail

input="$(cat)"

command_text="$(printf '%s' "$input" | python3 -c '
import json, sys
try:
    print(json.load(sys.stdin).get("tool_input", {}).get("command", ""))
except Exception:
    pass
' 2>/dev/null)"

[[ -z "$command_text" ]] && exit 0

# Each rule is "extended-regex<TAB>reason shown to Claude".
RULES=(
    $'(^|[;&|[:space:]])rm[[:space:]]+-[a-zA-Z]*([rR][a-zA-Z]*f|f[a-zA-Z]*[rR])[a-zA-Z]*[[:space:]]+(/|~|\\$HOME|/\\*|~/\\*)([[:space:]]|$)\trecursive force-delete of the filesystem root or home directory'
    $'git[[:space:]]+push([[:space:]]+[^;&|]*)?[[:space:]](--force|-f)([[:space:]]|$)\tforce push; use --force-with-lease on a branch you own, after the user approves it'
    $'(curl|wget)[^|;&]*\\|[[:space:]]*(sudo[[:space:]]+)?(ba|z|da)?sh([[:space:]]|$)\tpiping a downloaded script straight into a shell; download it, read it, then run it'
)

for rule in "${RULES[@]}"; do
    pattern="${rule%%$'\t'*}"
    reason="${rule#*$'\t'}"
    if [[ "$command_text" =~ $pattern ]]; then
        printf 'Blocked by .claude/hooks/pre-tool-use.sh: %s.\n' "$reason" >&2
        exit 2
    fi
done

exit 0
